"use client";
import { ArtemisScope } from "./artemis-scope";
import type { ArtemisFooterContent } from "./components/footer-sections/content";
import View2 from "./components/footer-sections/variants/03-landscape";
const variants = {"landscape":View2};
export type { ArtemisFooterClock, ArtemisFooterColumn, ArtemisFooterColumnLink, ArtemisFooterContent, ArtemisFooterImage, ArtemisFooterLink, ArtemisFooterNewsletter, ArtemisFooterSocialLink } from "./components/footer-sections/content";
export interface ArtemisFooterSectionsProps { className?: string; variant?: "landscape"; /** The words on the footer; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisFooterContent>; }
export function ArtemisFooterSections({ className, variant = "landscape", content }: ArtemisFooterSectionsProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View content={content}/></div></ArtemisScope>;}

// @zeus-internal
import type { ComponentType } from "react";

/** The words on a link, and where it goes. Links to other sites (http or https) open in a new tab. */
export interface ArtemisFooterLink {
  label: string;
  href: string;
}

/** A link in a column. */
export interface ArtemisFooterColumnLink extends ArtemisFooterLink {
  /** Shows the link in the stronger style, for a "browse all" link. landscape. */
  highlight?: boolean;
}

/** A small heading over a list of links. */
export interface ArtemisFooterColumn {
  title: string;
  links: ArtemisFooterColumnLink[];
}

/** A profile or contact link drawn as an icon. Its label names the link for screen readers, and is its tooltip where the layout has one. */
export interface ArtemisFooterSocialLink extends ArtemisFooterLink {
  /** The icon. Without one, the link keeps the icon the layout draws in that position. */
  icon?: ComponentType<{ className?: string }>;
}

/** A picture, and the words that describe it. */
export interface ArtemisFooterImage {
  src: string;
  alt: string;
}

/** An email sign-up form. */
export interface ArtemisFooterNewsletter {
  /** The heading over the form. */
  title: string;
  /** A line under the heading. */
  text: string;
  /** Sample text in the empty email field. */
  placeholder: string;
  /** The button. */
  button: string;
  /** The button while the address is being sent. */
  sending: string;
  /** The button once the address is sent. */
  sent: string;
}

/** A live clock for one city. */
export interface ArtemisFooterClock {
  /** The city named beside the clock face. */
  city: string;
  /** The city's IANA time zone, such as "Europe/Copenhagen". The clock stays blank if the zone is unknown. */
  timeZone: string;
  /** A line over the time. */
  caption: string;
}

/** The words on an Artemis footer. Every layout reads this shape, so you can switch layouts and keep them. */
export interface ArtemisFooterContent {
  /** The name beside the logo mark, and where it links. All layouts; wordmark, spotlight and mega show the name without a link, and wordmark and spotlight also draw it large across the foot. */
  brand: ArtemisFooterLink;
  /** A sentence about the brand. landscape, studio, local-time, frame, spotlight, mega and cta. */
  tagline?: string;
  /** The footer's main line. panorama and wordmark show it as a heading, landscape as a line under `tagline`, studio as a line over `cta`. */
  headline?: string;
  /** The styled end of the headline. It goes with `headline`: give `headline` alone and it shows alone, give both and both show. panorama, wordmark and landscape style it; studio runs it on after `headline`. */
  headlineAccent?: string;
  /** A paragraph under the headline. panorama. */
  subhead?: string;
  /** The main link. panorama and wordmark show it as a button, studio as a large underlined link. */
  cta?: ArtemisFooterLink;
  /** A quieter button beside `cta`. panorama. */
  secondaryCta?: ArtemisFooterLink;
  /** A short status, such as availability. studio and mega show it in a pill with a dot. */
  status?: string;
  /** A picture. panorama shows it wide; studio shows it over `location`. */
  image?: ArtemisFooterImage;
  /** Where you are, beside a map pin. studio. */
  location?: string;
  /** A row of links without headings. panorama and studio, which list the links of `columns` instead when you give only those. */
  links?: ArtemisFooterLink[];
  /** Columns of links under small headings. wordmark, landscape, local-time, frame, spotlight, mega and cta. */
  columns?: ArtemisFooterColumn[];
  /** An email sign-up form. mega. */
  newsletter?: ArtemisFooterNewsletter;
  /** A live clock for one city. local-time. */
  clock?: ArtemisFooterClock;
  /** Icon links to profiles or email. panorama, landscape, studio, frame, mega and cta. */
  social?: ArtemisFooterSocialLink[];
  /** The copyright line. All layouts but landscape. */
  legal?: string;
  /** Small links beside the copyright line. panorama, studio, local-time, frame and cta. */
  legalLinks?: ArtemisFooterLink[];
  /** A short closing line near the copyright. wordmark, frame and spotlight. */
  note?: string;
}

"use client";
// @zeus-internal
import { MotionConfig, motion } from "motion/react";
import { ARTEMIS_EASE_OUT } from "../../../lib/ease";
import type { ArtemisFooterContent, ArtemisFooterSocialLink } from "../content";
const COLUMN_HIDDEN = { opacity: 0, y: 10 } as const;
const COLUMN_SHOWN = { opacity: 1, y: 0 } as const;
const columnTransition = (index: number) => ({ duration: 0.4, ease: ARTEMIS_EASE_OUT, delay: index * 0.05 });
const DEFAULT = {
    brand: { label: "Artemis Pro", href: "/" },
    tagline: "Premium motion components, illustrations, blocks, and full templates \u2014 ready to make your own.",
    headline: "Ready for",
    headlineAccent: "your next project",
    social: [{ label: "Email", href: "mailto:hello@example.com" }],
    columns: [
        { title: "Components", links: [{ label: "Agent chat input", href: "/components/agent-chat-input" }, { label: "Model picker", href: "/components/model-picker" }, { label: "Stats", href: "/components/stats" }, { label: "Browse components", href: "/components", highlight: true }] },
        { title: "Blocks", links: [{ label: "Hero sections", href: "/components/hero-sections" }, { label: "CTA sections", href: "/components/cta-sections" }, { label: "Footer sections", href: "/components/footer-sections" }, { label: "Pricing", href: "/components/pricing" }, { label: "Browse blocks", href: "/components", highlight: true }] },
        { title: "Illustrations", links: [{ label: "Explore illustrations", href: "/illustrations" }, { label: "What\u2019s new", href: "/changelog" }, { label: "Source access", href: "/#pricing" }] },
        { title: "Templates", links: [{ label: "Landing pages", href: "/components/categories/templates" }, { label: "Browse templates", href: "/components/categories/templates" }, { label: "Installation", href: "/components/installation" }] },
        { title: "Links", links: [{ label: "Changelog", href: "/changelog" }, { label: "Contact", href: "/contact" }, { label: "Pricing", href: "/#pricing" }, { label: "For AI agents", href: "/components/agents" }, { label: "FAQs", href: "/#faqs" }, { label: "Artemis Free", href: "https://example.com" }] },
    ],
} satisfies ArtemisFooterContent;
/** The layout's own icons in order, for social links that come without one. */
const SOCIAL_ICONS = [
    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-mail art:size-4" aria-hidden="true">
      <path d="m22 7-8.991 5.727a2 2 0 0 1-2.009 0L2 7"/>
      <rect x="2" y="4" width="20" height="16" rx="2"/>
    </svg>,
];
/** Links to other sites open in a new tab. */
const newTab = (href: string) => (/^https?:/.test(href) ? { target: "_blank", rel: "noreferrer noopener" } : {});
export default function FooterSectionsLandscape({ content }: { content?: Partial<ArtemisFooterContent> } = {}) {
    const copy = { ...DEFAULT, ...content };
    const accent = content?.headline === undefined ? copy.headlineAccent : content.headlineAccent;
    const social: ArtemisFooterSocialLink[] = copy.social;
    return (<MotionConfig reducedMotion="user">
      <footer className="art:relative art:isolate art:w-full art:overflow-hidden art:border-t art:border-border art:bg-background art:text-foreground">
        <div className="art:relative art:z-10 art:mx-auto art:grid art:max-w-6xl art:grid-cols-2 art:gap-x-6 art:gap-y-10 art:px-5 art:pt-14 art:@min-[640px]/artemis:px-8 art:@min-[1024px]/artemis:grid-cols-[1.5fr_repeat(5,minmax(0,1fr))] art:pb-48 art:@min-[640px]/artemis:pb-64">
          <div className="art:col-span-2 art:max-w-xs art:@min-[1024px]/artemis:col-span-1">
            <a href={copy.brand.href} {...newTab(copy.brand.href)} className="art:inline-flex art:min-h-10 art:items-center art:gap-2.5 art:rounded-full art:text-lg art:font-medium art:focus-visible:outline-2 art:focus-visible:outline-offset-4 art:focus-visible:outline-ring">
              <span aria-hidden="true" className="art:grid art:size-8 art:place-items-center art:rounded-full art:border art:border-border">
                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-layers art:size-5" aria-hidden="true">
                  <path d="M12.83 2.18a2 2 0 0 0-1.66 0L2.6 6.08a1 1 0 0 0 0 1.83l8.58 3.91a2 2 0 0 0 1.66 0l8.58-3.9a1 1 0 0 0 0-1.83z"/>
                  <path d="M2 12a1 1 0 0 0 .58.91l8.6 3.91a2 2 0 0 0 1.65 0l8.58-3.9A1 1 0 0 0 22 12"/>
                  <path d="M2 17a1 1 0 0 0 .58.91l8.6 3.91a2 2 0 0 0 1.65 0l8.58-3.9A1 1 0 0 0 22 17"/>
                </svg>
              </span>
              {copy.brand.label}
            </a>
            <p className="art:mt-4 art:text-sm art:leading-6 art:text-muted-foreground">
              {copy.tagline}
            </p>
            <p className="art:mt-4 art:text-sm art:text-muted-foreground">
              {accent ? `${copy.headline} ` : copy.headline}
              {accent ? (<span className="art:text-foreground">
                {accent}
              </span>) : null}
            </p>
            <div className="art:mt-4 art:flex art:flex-wrap art:items-center art:gap-1">
              {social.map((link, index) => {
                const Icon = link.icon;
                return <a key={index} href={link.href} {...newTab(link.href)} aria-label={link.label} className="art:grid art:size-10 art:place-items-center art:rounded-full art:text-muted-foreground art:transition-colors art:hover:bg-muted art:hover:text-foreground art:focus-visible:outline-2 art:focus-visible:outline-ring">
                  <span aria-hidden="true">
                    {Icon ? <Icon className="art:size-4"/> : SOCIAL_ICONS[index % SOCIAL_ICONS.length]}
                  </span>
                </a>;
              })}
            </div>
          </div>
          {copy.columns.map((column, index) => <motion.nav key={index} aria-label={column.title} initial={COLUMN_HIDDEN} whileInView={COLUMN_SHOWN} viewport={{ once: true }} transition={columnTransition(index)}>
            <h2 className="art:text-xs art:font-medium art:uppercase art:tracking-wider art:text-muted-foreground">
              {column.title}
            </h2>
            <ul className="art:mt-4 art:space-y-1">
              {column.links.map((link, linkIndex) => <li key={linkIndex}>
                <a href={link.href} {...newTab(link.href)} className={link.highlight ? "art:inline-flex art:min-h-9 art:items-center art:text-sm art:transition-colors art:hover:text-foreground art:focus-visible:rounded-full art:focus-visible:outline-2 art:focus-visible:outline-offset-4 art:focus-visible:outline-ring art:font-medium art:text-foreground" : "art:inline-flex art:min-h-9 art:items-center art:text-sm art:text-muted-foreground art:transition-colors art:hover:text-foreground art:focus-visible:rounded-full art:focus-visible:outline-2 art:focus-visible:outline-offset-4 art:focus-visible:outline-ring"}>
                  {link.label}
                </a>
              </li>)}
            </ul>
          </motion.nav>)}
        </div>
        <div aria-hidden="true" className="art:pointer-events-none art:absolute art:inset-x-0 art:bottom-0 art:h-96 art:[mask-image:linear-gradient(to_bottom,transparent,black_80%)] art:@min-[640px]/artemis:h-[520px]">
          <img src="/assets/artemis/1973c2217051e699c5de.webp" alt="" loading="lazy" className="art:size-full art:object-cover art:object-bottom art:dark:brightness-50"/>
        </div>
      </footer>
    </MotionConfig>);
}
